// EncodeExecutionRequests (proto/engine/v1/electra.go)
func EncodeExecutionRequests(requests *ExecutionRequests) ([]hexutil.Bytes, error) {
    requestsData := make([]hexutil.Bytes, 0)
    // request types MUST be in sorted order starting from 0
    if len(requests.Deposits) > 0 {
        requestData := []byte{DepositRequestType}  // 0
        requestsData = append(requestsData, requestData)
    }
    if len(requests.Withdrawals) > 0 {
        requestData := []byte{WithdrawalRequestType}  // 1
        requestsData = append(requestsData, requestData)
    }
    if len(requests.Consolidations) > 0 {
        requestData := []byte{ConsolidationRequestType}  // 2
        requestsData = append(requestsData, requestData)
    }
    return requestsData, nil
}

// GetDecodedExecutionRequests enforces order on decode
if prevTypeNum != nil && *prevTypeNum >= requestType {
    return nil, errors.New("invalid execution request type order or duplicate requests")
}

func ProcessDepositRequests(ctx context.Context, beaconState state.BeaconState, requests []*enginev1.DepositRequest) (state.BeaconState, error) {
    if len(requests) == 0 { return beaconState, nil }
    for _, receipt := range requests {
        beaconState, err = processDepositRequest(beaconState, receipt)
        if err != nil { return nil, errors.Wrap(err, "could not apply deposit request") }
    }
    return beaconState, nil
}

func processDepositRequest(beaconState state.BeaconState, request *enginev1.DepositRequest) (state.BeaconState, error) {
    // Sets DepositRequestsStartIndex and appends PendingDeposit with current slot
    if requestsStartIndex == params.BeaconConfig().UnsetDepositRequestsStartIndex {
        if err := beaconState.SetDepositRequestsStartIndex(request.Index); err != nil { ... }
    }
    if err := beaconState.AppendPendingDeposit(&ethpb.PendingDeposit{
        PublicKey:             bytesutil.SafeCopyBytes(request.Pubkey),
        WithdrawalCredentials: bytesutil.SafeCopyBytes(request.WithdrawalCredentials),
        Amount:                request.Amount,
        Signature:             bytesutil.SafeCopyBytes(request.Signature),
        Slot:                  beaconState.Slot(),
    }); err != nil { ... }
    return beaconState, nil
}

// ProcessConsolidationRequests (beacon-chain/core/electra/consolidations.go)
if IsValidSwitchToCompoundingRequest(st, cr) {
    srcIdx, ok := st.ValidatorIndexByPubkey(bytesutil.ToBytes48(cr.SourcePubkey))
    if !ok {
        log.Error("Failed to find source validator index")
        continue
    }
    if err := SwitchToCompoundingValidator(st, srcIdx); err != nil {
        log.WithError(err).Error("Failed to switch to compounding validator")
        // ERROR IS SWALLOWED — no return, no state rollback
    }
    continue
}

// SwitchToCompoundingValidator performs TWO state mutations:
// 1. UpdateValidatorAtIndex (sets withdrawal credential prefix to 0x02)
// 2. QueueExcessActiveBalance (drains balance + AppendPendingDeposit)
// If mutation 2 fails, mutation 1 is NOT rolled back.

